plt.xlabel('Số lượng cụm (k)')
plt.ylabel('Inertia (WCSS)')
plt.grid(True, linestyle='--', alpha=0.6)
plt.show()

print("--- GIẢI THÍCH CHỌN k ---")
print("Dựa vào đồ thị Elbow, ta thấy 'điểm gãy' (elbow) rõ rệt nhất nằm ở k=3. Từ k=1 đến k=3, giá trị Inertia giảm rất dốc, nhưng từ k=3 trở đi, tốc độ giảm chậm lại và dần đi ngang. Do đó, chọn k=3 là số cụm tối ưu nhất.")
